"""Emit a PyInstaller version-info file for the desktop build (ADR-021).

Usage:  python scripts/make_version_info.py > desktop/version_info.txt

Reads ledgerforge.__version__, so the .exe's Windows properties can never
drift from the package. Generated — do not edit the output by hand.
"""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from ledgerforge import __version__  # noqa: E402

numeric = tuple(int(part) for part in __version__.split(".")[:3]) + (0,)

TEMPLATE = f"""# UTF-8
#
# Generated by scripts/make_version_info.py from ledgerforge {__version__}.
VSVersionInfo(
  ffi=FixedFileInfo(
    filevers={numeric},
    prodvers={numeric},
    mask=0x3f,
    flags=0x0,
    OS=0x40004,
    fileType=0x1,
    subtype=0x0,
    date=(0, 0)
  ),
  kids=[
    StringFileInfo(
      [
      StringTable(
        '040904B0',
        [StringStruct('CompanyName', 'mir-ashiq / LedgerForge community'),
        StringStruct(
          'FileDescription',
          'LedgerForge Desktop - keyboard-first double-entry bookkeeping'
        ),
        StringStruct('FileVersion', '{__version__}'),
        StringStruct('InternalName', 'LedgerForge'),
        StringStruct(
          'LegalCopyright',
          'AGPL-3.0-only - https://github.com/mir-ashiq/ledgerforge'
        ),
        StringStruct('OriginalFilename', 'LedgerForge.exe'),
        StringStruct('ProductName', 'LedgerForge Desktop'),
        StringStruct('ProductVersion', '{__version__}')])
      ]),
    VarFileInfo([VarStruct('Translation', [1033, 1200])])
  ]
)
"""

sys.stdout.write(TEMPLATE)
